from math import hypot
pts=[(1,2),(2,13),(2,15),(2,23),(3,1),(3,19),(4,14),(5,2),(5,25),(6,22),(8,15),(9,8),(10,4),(11,1),(11,24),(13,11),(16,6),(16,8),(17,26),(19,16),(19,20),(20,2),(20,11),(20,14),(21,6),(22,20),(22,22)]
for i,p in enumerate(pts):
    ds=sorted((hypot(p[0]-q[0],p[1]-q[1]),j+1,q) for j,q in enumerate(pts) if j!=i)
    print(f'{i+1:2} {p}: nearest '+', '.join(f'{d:.2f}#{j}{q}' for d,j,q in ds[:3]))
print('\nChebyshev components:')
for t in [1,2,3,4,5,6,7]:
    un=set(range(len(pts))); comps=[]
    while un:
      todo=[un.pop()]; comp=[]
      while todo:
        i=todo.pop(); comp.append(i)
        near=[j for j in list(un) if max(abs(pts[i][0]-pts[j][0]),abs(pts[i][1]-pts[j][1]))<=t]
        for j in near: un.remove(j); todo.append(j)
      comps.append(comp)
    print(t, sorted([len(c) for c in comps],reverse=True), [[j+1 for j in c] for c in sorted(comps,key=len,reverse=True)])

